{"file_path":"/Users/alex/code/acme-shop/test/server.test.js","content":"import { test } from "node:test";
import assert from "node:assert/strict";
import { handle } from "../src/server.js";

const get = (url) => handle({ method: "GET", url }).body;

test("paginates with defaults", () => {
  const body = get("/products");
  assert.equal(body.page, 1);
  assert.equal(body.pageSize, 20);
  assert.equal(body.total, 57);
  assert.equal(body.items.length, 20);
  assert.equal(body.items[0].id, 1);
});

test("returns the requested page", () => {
  const body = get("/products?page=2&pageSize=10");
  assert.equal(body.items.length, 10);
  assert.equal(body.items[0].id, 11);
});

test("last page is partial", () => {
  const body = get("/products?page=3");
  assert.equal(body.items.length, 17);
});

test("page past the end is empty", () => {
  const body = get("/products?page=99");
  assert.deepEqual(body.items, []);
  assert.equal(body.total, 57);
});

test("pageSize is capped at 100", () => {
  const body = get("/products?pageSize=500");
  assert.equal(body.pageSize, 100);
  assert.equal(body.items.length, 57);
});

test("invalid page params fall back or clamp", () => {
  const body = get("/products?page=abc&pageSize=0");
  assert.equal(body.page, 1);
  assert.equal(body.pageSize, 1);
  assert.equal(get("/products?page=-5").page, 1);
});

test("total reflects the category filter", () => {
  const body = get("/products?category=garden&pageSize=5");
  assert.equal(body.total, 14);
  assert.equal(body.items.length, 5);
  assert.ok(body.items.every((p) => p.category === "garden"));
});
